const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakePoint = ee.Geometry.Point([-121.39, 47.33]); // Keechelus Lake center
  const roi = lakePoint.buffer(2000); // Buffer for lake area
  const dates = {
    '2024': ['2024-07-01', '2024-07-31'],
    '2025': ['2025-07-01', '2025-07-31']
  };

  // 2. Data Acquisition
  function getWaterCollection(start, end) {
    return ee.ImageCollection('JRC/GSW1_4/YearlyHistory')
      .filterBounds(roi)
      .filterDate(start, end)
      .select('waterClass');
  }

  // Check data availability
  const col2024 = getWaterCollection(dates['2024'][0], dates['2024'][1]);
  const col2025 = getWaterCollection(dates['2025'][0], dates['2025'][1]);

  const size2024 = col2024.size().getInfo();
  const size2025 = col2025.size().getInfo();

  console.log(`2024 Images: ${size2024}, 2025 Images: ${size2025}`);

  if (size2024 === 0 || size2025 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get annual water classification images
  const img2024 = col2024.first();
  const img2025 = col2025.first();

  // 3. Processing: Extract water pixels (classes 2,3 = water, class 1 = no data)
  function getWaterArea(img) {
    // Water classes: 2 (seasonal water), 3 (permanent water)
    const waterMask = img.eq(2).or(img.eq(3));
    return waterMask.selfMask();
  }

  const water2024 = getWaterArea(img2024);
  const water2025 = getWaterArea(img2025);

  // 4. Calculation: Count water pixels
  const stats2024 = water2024.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  });

  const stats2025 = water2025.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  });

  const count2024 = stats2024.get('waterClass').getInfo();
  const count2025 = stats2025.get('waterClass').getInfo();

  console.log(`2024 Water pixels: ${count2024}, 2025 Water pixels: ${count2025}`);

  // 5. Validation & Final Answer
  if (count2024 === null || count2025 === null || 
      count2024 === undefined || count2025 === undefined) {
    console.log("<answer>C3</answer>");
  } else if (count2024 === 0 || count2025 === 0) {
    console.log("<answer>C2</answer>");
  } else {
    const decrease = count2025 < count2024;
    console.log(`Water extent ${decrease ? 'decreased' : 'increased/unchanged'}`);
    console.log(decrease ? "<answer>A</answer>" : "<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
